// The single published Android artifact: the uniffi-generated Kotlin
// bindings, the per-ABI Rust libraries and the idiomatic `MapView`/Compose
// wrapper in one AAR, so an application adds one dependency. The generated
// sources and `jniLibs` live under `:map-sdk-native` (regenerated by
// `scripts/build-android.sh`) and are compiled into this module's source
// sets; that module is an internal source holder, not a second artifact.
plugins {
    id("com.android.library") version "9.0.0"
    // Compose's compiler plugin matches the Kotlin release the Android Gradle
    // Plugin 9.0.0 embeds (validated matrix: Kotlin 2.2.21). It is needed to
    // compile the optional Compose `MapView` wrapper; the Compose runtime
    // itself is a `compileOnly` input (see the dependencies block).
    id("org.jetbrains.kotlin.plugin.compose") version "2.2.21"
    `maven-publish`
}

// Packaging identity of the released AAR (docs/PackagingAndRelease.md §1
// ruling 2): Maven group `com.angoratek`, artifact `rustic-maps-sdk`, one
// artifact for bindings, native libraries and wrapper.
group = "com.angoratek"
version = "0.1.0"

android {
    namespace = "com.rusticmaps.sdk"
    compileSdk = 36

    defaultConfig {
        minSdk = 24
        // The `Java_com_rusticmaps_sdk_NativeWindowBridge_*` symbols in
        // `librustic_maps.so` are bound to an exact Kotlin class name, so a
        // consuming app's R8 pass must not rename or strip that class.
        consumerProguardFiles("../map-sdk-native/consumer-rules.pro")
    }

    sourceSets.getByName("main") {
        // The generated bindings and the three ABI libraries are inputs of
        // this module, not a dependency on a second artifact.
        kotlin.srcDir("../map-sdk-native/src/main/kotlin")
        jniLibs.srcDir("../map-sdk-native/src/main/jniLibs")
        // Package-level notices (docs/PackagingAndRelease.md §4.4), staged by
        // scripts/build-android.sh before the release assembly runs.
        assets.srcDir("../map-sdk-native/build/generated/sdk-licenses")
    }

    // The single `release` variant is the published AAR surface.
    publishing {
        singleVariant("release")
    }

    compileOptions {
        sourceCompatibility = JavaVersion.VERSION_17
        targetCompatibility = JavaVersion.VERSION_17
    }
    // Lint gates the release: an error fails the build instead of leaving the
    // published AAR unchecked. Warnings stay warnings (the generated bindings
    // carry style-only diagnostics of their own).
    lint {
        abortOnError = true
    }
}

kotlin {
    compilerOptions {
        jvmTarget.set(org.jetbrains.kotlin.gradle.dsl.JvmTarget.JVM_17)
        // Compile the listener interface's defaults as JVM default methods
        // (the annotation above the interface adds the compatibility bridge
        // for already-compiled callers), so a Java or Kotlin implementor that
        // overrides only some callbacks never hits an AbstractMethodError.
        freeCompilerArgs.add("-jvm-default=no-compatibility")
    }
}

dependencies {
    val composeBom = platform("androidx.compose:compose-bom:2026.06.01")
    // The descriptor-driven registration rules are pure Kotlin and run as
    // plain JVM unit tests, without loading the native library. The Compose
    // compiler plugin still checks the unit-test compile classpath for a
    // Compose runtime, so the test source set carries one (it does not affect
    // the published POM).
    testImplementation("junit:junit:4.13.2")
    testImplementation(composeBom)
    testImplementation("androidx.compose.runtime:runtime")

    implementation("net.java.dev.jna:jna:5.18.1@aar")
    implementation("org.jetbrains.kotlinx:kotlinx-coroutines-core:1.10.2")

    // The Compose wrapper is optional: the published POM must not force the
    // Compose runtime on a consumer that never hosts the composable, so the
    // Compose artifacts are compile-time only. A Compose host supplies them
    // from its own BOM, exactly as its application module already does.
    compileOnly(composeBom)
    compileOnly("androidx.compose.ui:ui")
    // The Compose `MapView` wrapper drives the view's onStart/onStop from the
    // host lifecycle (`LocalLifecycleOwner`).
    compileOnly("androidx.lifecycle:lifecycle-runtime-compose:2.9.4")
}

// The generated bindings and per-ABI libraries are produced by
// `scripts/build-android.sh` into the internal source holder. A direct Gradle
// invocation on a clean checkout would otherwise fail with unresolved
// references deep in the compile; fail fast with that instruction instead.
val generatedBindingsDirectory = layout.projectDirectory.dir("../map-sdk-native/src/main/kotlin")
val generatedJniLibsDirectory = layout.projectDirectory.dir("../map-sdk-native/src/main/jniLibs")
val assertGeneratedSourcesPresent = tasks.register("assertGeneratedSourcesPresent") {
    doLast {
        val missingPaths = listOf(generatedBindingsDirectory, generatedJniLibsDirectory)
            .filter { directory -> !directory.asFile.isDirectory || directory.asFile.list().isNullOrEmpty() }
            .map { directory -> directory.asFile.relativeTo(rootDir).path }
        if (missingPaths.isNotEmpty()) {
            throw GradleException(
                "the generated Android bindings are missing (${missingPaths.joinToString()}); " +
                    "run scripts/build-android.sh to generate the Kotlin bindings and per-ABI libraries",
            )
        }
    }
}
tasks.named("preBuild") {
    dependsOn(assertGeneratedSourcesPresent)
}

afterEvaluate {
    publishing {
        publications {
            // `from(components["release"])` publishes the AAR and carries the
            // runtime dependencies into the generated POM, so a consumer's
            // dependency resolution is exact.
            create<MavenPublication>("release") {
                from(components["release"])
                artifactId = "rustic-maps-sdk"
                pom {
                    name.set("Rustic Maps SDK for Android")
                    description.set(
                        "Kotlin bindings, native libraries and the MapView wrapper " +
                            "for the Rustic Maps SDK, generated from the frozen UniFFI contract.",
                    )
                    url.set("https://github.com/angoratek/rustic-maps-sdk")
                    licenses {
                        license {
                            name.set("MIT OR Apache-2.0")
                            url.set("https://github.com/angoratek/rustic-maps-sdk#license")
                        }
                    }
                    scm {
                        connection.set("scm:git:https://github.com/angoratek/rustic-maps-sdk.git")
                        developerConnection.set("scm:git:ssh://git@github.com/angoratek/rustic-maps-sdk.git")
                        url.set("https://github.com/angoratek/rustic-maps-sdk")
                    }
                }
            }
        }
    }
}
